{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/pizza-picker.json
    Pizzas with a picker on each card: the picture, name and toppings, a radio group of sizes and one of crusts (each a fieldset with role radiogroup), the price and an add button. Axes: layout (cards, rows), tone.
    Props (p): id, title, lead, dishes, empty, labels, sizes, crusts, layout, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_dishes = ($p['dishes'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_sizes = ($p['sizes'] ?? null)}
{var $v_crusts = ($p['crusts'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'cards')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_10}
  {if og_t(og_eq(og_len($v_dishes), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'star', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_9}
      {foreach og_l($v_dishes) as $v_d}
        {capture $c_8}
          {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_d, ['name']), 'ratio' => '1/1']])|noescape}
          {capture $c_7}
            {capture $c_3}
              {capture $c_1}
                {=og_text(og_get($v_d, ['name']))}
              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'lg', 'weight' => 'semibold', 'children' => (string) $c_1])|noescape}
              {capture $c_2}
                {=og_text(og_get($v_d, ['summary']))}
              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
            {/capture}
            {=og_include('compose/Stack.latte', ['gap' => '2', 'children' => (string) $c_3])|noescape}
            {=og_include('blocks/option-chips.latte', ['p' => ['name' => og_tpl('{0}-size-{1}', [$v_id, og_get($v_d, ['id'])]), 'legend' => og_get($v_labels, ['size']), 'options' => $v_sizes]])|noescape}
            {=og_include('blocks/option-chips.latte', ['p' => ['name' => og_tpl('{0}-crust-{1}', [$v_id, og_get($v_d, ['id'])]), 'legend' => og_get($v_labels, ['crust']), 'options' => $v_crusts]])|noescape}
            {capture $c_6}
              {capture $c_4}
                {=og_text(og_money(og_get($v_d, ['price']), og_get($v_d, ['currency'])))}
              {/capture}
              {=og_include('compose/Inline.latte', ['class' => 'text-xl font-bold', 'children' => (string) $c_4])|noescape}
              {capture $c_5}
                {=og_text(og_get($v_labels, ['add']))}
              {/capture}
              {=og_include('compose/Button.latte', ['variant' => 'default', 'size' => 'default', 'type' => 'button', 'ariaLabel' => og_s(og_tpl(og_get($v_labels, ['addOf']), [og_get($v_d, ['name'])])), 'children' => (string) $c_5])|noescape}
            {/capture}
            {=og_include('compose/Group.latte', ['gap' => '4', 'align' => 'center', 'justify' => 'between', 'class' => 'mt-auto', 'children' => (string) $c_6])|noescape}
          {/capture}
          {=og_include('compose/Stack.latte', ['gap' => '4', 'class' => og_s((og_t(og_eq($v_layout, 'rows')) ? 'md:col-span-2' : '')), 'children' => (string) $c_7])|noescape}
        {/capture}
        {=og_include('compose/Box.latte', ['class' => og_s((og_t(og_eq($v_layout, 'rows')) ? 'rounded bg-card inset-ring inset-ring-border grid grid-cols-1 gap-4 p-4 md:grid-cols-3' : 'rounded bg-card inset-ring inset-ring-border flex flex-col gap-4 p-4')), 'attrs' => og_attrs(['data-slot', 'item']), 'children' => (string) $c_8])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Box.latte', ['class' => og_s((og_t(og_eq($v_layout, 'rows')) ? 'flex flex-col gap-4' : 'grid grid-cols-1 gap-4 md:grid-cols-3')), 'attrs' => og_attrs(['data-slot', 'items']), 'children' => (string) $c_9])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_10)])|noescape}
